		{"raw"},
		{"mid", "raw"},
		{"x", "mid"},
	})

	out := mustExportScoped(t, graph, "mid", "mid")
	if want := `{"nodes":["mid"],"edges":[]}`; out != want {
		t.Errorf("export = %s, want %s", out, want)
	}
	doc := parseExport(t, out)
	if doc.Edges == nil {
		t.Errorf("edges must decode as an empty array, got nil from %s", out)
	}
