			if doc.Nodes == nil {
				t.Errorf("nodes must decode as an empty array, got nil from %s", out)
			}
			if doc.Edges == nil {
				t.Errorf("edges must decode as an empty array, got nil from %s", out)
			}
		})
	}
	assertGraphUnchanged(t, before, graph)
